import '@testing-library/jest-dom/vitest'

import { render, screen, waitFor } from '@testing-library/react'
import { MemoryRouter } from 'react-router-dom'
import { describe, expect, it, vi } from 'vitest'

const mocks = vi.hoisted(() => ({ getFamilyDashboard: vi.fn() }))
vi.mock('../../services/apiClient', () => ({ threePortalApi: mocks }))

import { FamilyDashboardPanel } from './FamilyDashboardPanel'

const baseDashboard = {
  role: 'Head',
  familyName: 'Silva Family',
  familyCode: 'FV-ABCDEF',
  memberCount: 4,
  minorCount: 2,
  pendingJoinRequests: 3,
  nextAppointment: null,
  openCases: 1,
  approvedGuidanceCount: 2,
  familyDoctor: null,
  unreadNotifications: 0,
  recentActivity: [],
}

describe('FamilyDashboardPanel (Head)', () => {
  it('renders head metrics: members, open cases, join requests', async () => {
    mocks.getFamilyDashboard.mockResolvedValue({ data: baseDashboard })

    render(<MemoryRouter><FamilyDashboardPanel /></MemoryRouter>)

    await waitFor(() => expect(screen.getByText('4')).toBeInTheDocument())
    expect(screen.getByText('1')).toBeInTheDocument()
    expect(screen.getByText('3')).toBeInTheDocument()
    expect(screen.getByText('Add minor')).toBeInTheDocument()
  })
})
